def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None:
        sites = s.get('sites') or []
        total = 0.0
        for site in sites:
            o = site.get('occupancy')
            total += max(0.0, o if o is not None else 1.0)
        volume = (s.get('lattice') or {}).get('volume_A3')
        v = volume / total if volume is not None and total > 0 else 0.0
    return log1p(max(0.0, v))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    total = 0.0
    sphere = 0.0
    for site in sites:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        volume = v * total if v is not None else 0.0
    if volume <= 0:
        return 0.0
    return (4.0 * pi / 3.0) * sphere / volume

