def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = []
    amounts = {}
    for site in sites:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occ.append(o)
        element = site.get('element')
        amounts[element] = amounts.get(element, 0.0) + o
    total = sum(occ)
    if total <= 0:
        return 0.0
    expected = 1.0 - sum((a / total) ** 2 for a in amounts.values())
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and nearest[i] < inf and d <= 2.0 * nearest[i]:
            w = occ[i] * occ[j] * exp(1.0 - (d / nearest[i]) ** 6)
            weight += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return unlike / weight - expected if weight > 0 else 0.0

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    data = []
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0:
            continue
        p = props.get(element) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is None or affinity is None or ion <= 0:
            continue
        chi = 0.5 * (ion + affinity)
        hardness = max(0.1, ion - affinity)
        data.append((fraction, chi, hardness))
    total = sum(a[0] for a in data)
    denominator = sum(a[0] / a[2] for a in data)
    if total <= 0 or denominator <= 0:
        return 0.0
    mu = sum(a[0] * a[1] / a[2] for a in data) / denominator
    return -0.5 * sum(a[0] * (a[1] - mu) ** 2 / a[2] for a in data) / total

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    data = {}
    numerator = 0.0
    denominator = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0:
            continue
        p = props.get(element) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is None or affinity is None or ion <= 0:
            continue
        chi = 0.5 * (ion + affinity)
        hardness = max(0.1, ion - affinity)
        data[element] = (chi, hardness)
        numerator += fraction * chi / hardness
        denominator += fraction / hardness
    if denominator <= 0:
        return 0.0
    mu = numerator / denominator
    charges = {}
    for element, pair in data.items():
        charges[element] = (mu - pair[0]) / pair[1]
    sites = s.get('sites') or []
    n = len(sites)
    q = []
    occ = []
    for site in sites:
        q.append(charges.get(site.get('element'), 0.0))
        o = site.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    total = sum(occ)
    if total <= 0:
        return 0.0
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and 0 < d < 6.0:
            taper = (1.0 - (d / 6.0) ** 2) ** 2
            value += occ[i] * occ[j] * q[i] * q[j] * taper / d
    return 7.19982274 * value / total

