    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    valence = []
    occ = []
    for site in sites:
        valence.append((props.get(site.get('element')) or {}).get('valence_electrons'))
        o = site.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    value = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and nearest[i] < inf and d <= 2.0 * nearest[i] and valence[i] is not None and valence[j] is not None:
            denominator = abs(valence[i]) + abs(valence[j])
            if denominator > 0:
                w = occ[i] * occ[j] * exp(1.0 - (d / nearest[i]) ** 6)
                value += w * abs(valence[i] - valence[j]) / denominator
                weight += w
    return value / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    density = s.get('density_g_cm3')
    if density is None:
        density = (s.get('basic_structure_statistics') or {}).get('density_g_cm3')
    if density is None:
        v = s.get('volume_per_atom_A3')
        props = s.get('element_properties') or {}
        mass = 0.0
        total = 0.0
        for element, fraction in (s.get('composition') or {}).items():
            m = (props.get(element) or {}).get('mass_amu')
            if fraction is not None and fraction > 0 and m is not None and m > 0:
                mass += fraction * m
                total += fraction
        if v is None or v <= 0 or total <= 0:
            return 0.0
        density = mass / (total * v * 0.602214076)
    return log1p(max(0.0, density))

